window.VO = [{"id":"o01","text":"You are under digital arrest.","at":0.24,"t0":0.12,"t1":1.885},{"id":"o02","text":"Do not hang up.","at":4.17,"t0":2.085,"t1":3.165},{"id":"n01","text":"Would you fall for this?","at":6.93,"t0":3.465,"t1":4.635},{"id":"n02","text":"Then find the three mistakes on this call.","at":11.17,"t0":5.585,"t1":7.595},{"id":"o03","text":"Again. A parcel in your name.","at":15.69,"t0":7.845,"t1":9.82},{"id":"o05","text":"Your pension account is frozen.","at":22.04,"t0":11.02,"t1":13.045},{"id":"o06","text":"Declare your gold, madam.","at":26.53,"t0":13.265,"t1":14.935},{"id":"o08","text":"Tell anyone, and they are arrested too.","at":30.37,"t0":15.185,"t1":17.345},{"id":"o09","text":"That is my team.","at":38.39,"t0":19.195,"t1":20.505},{"id":"n03","text":"You just looked at your door, didn't you?","at":41.61,"t0":20.805,"t1":22.455},{"id":"n04","text":"Even though his badge can't spell police.","at":45.21,"t0":22.605,"t1":24.665},{"id":"n05","text":"And even if it could, there's no such thing as a digital arrest.","at":49.63,"t0":24.815,"t1":28.145},{"id":"n06","text":"You only know that because somebody told you.","at":56.89,"t0":28.445,"t1":30.58},{"id":"n07","text":"Nobody told her.","at":61.66,"t0":30.83,"t1":31.91},{"id":"n08","text":"This was never your call.","at":65.52,"t0":32.76,"t1":34.17},{"id":"n09","text":"While you hunted for mistakes, she took off her bangles.","at":70.24,"t0":35.12,"t1":37.94},{"id":"n10","text":"She corrected spelling for thirty years, but she wasn't looking for his mistakes.","at":76.88,"t0":38.44,"t1":42.735},{"id":"n11","text":"She was trying to prove she hadn't made one.","at":86.17,"t0":43.085,"t1":45.13},{"id":"o10","text":"Madam.","at":95.96,"t0":47.98,"t1":48.725},{"id":"n12","text":"That was never his team.","at":98.25,"t0":49.125,"t1":50.49},{"id":"n13","text":"It was you.","at":101.58,"t0":50.79,"t1":51.585},{"id":"m01","text":"I'm fine, beta.","at":103.77,"t0":51.885,"t1":53.08},{"id":"m02","text":"You eat.","at":106.86,"t0":53.43,"t1":54.25},{"id":"n14","text":"So you did.","at":115,"t0":57.5,"t1":58.35},{"id":"n16","text":"You'd never fall for this.","at":123.6,"t0":61.8,"t1":63.21},{"id":"n17","text":"You would just believe her.","at":126.92,"t0":63.46,"t1":64.73},{"id":"n18","text":"Have you told your mother?","at":131.96,"t0":65.98,"t1":67.28},{"id":"n19","text":"Would she tell you?","at":135.76,"t0":67.88,"t1":68.925}];
